using System;using System.Linq;
namespace IdleIntelligence.Core {
 [Serializable]public sealed class LegacyFactor {public string key;public NumberData value;public LegacyFactor Copy()=>new LegacyFactor{key=key,value=ScientificNumber.FromData(value).ToData()};}
 [Serializable]public sealed class LegacyState {public string[] licenses=Array.Empty<string>(),autobuyers=Array.Empty<string>();public LegacyFactor[] cycle=Array.Empty<LegacyFactor>(),permanent=Array.Empty<LegacyFactor>();public double trainingBoostUntil;public int scannerTarget=-1;public bool prepared;public LegacyState Copy()=>new LegacyState{licenses=(string[])licenses.Clone(),autobuyers=(string[])autobuyers.Clone(),cycle=cycle.Select(x=>x.Copy()).ToArray(),permanent=permanent.Select(x=>x.Copy()).ToArray(),trainingBoostUntil=trainingBoostUntil,scannerTarget=scannerTarget,prepared=prepared};}
 public static class LegacyEffects {
  public static ScientificNumber Factor(GameState s,string key){var c=s.Legacy.cycle.FirstOrDefault(x=>x.key==key);var p=s.Legacy.permanent.FirstOrDefault(x=>x.key==key);return(c==null?ScientificNumber.One:ScientificNumber.FromData(c.value)).Multiply(p==null?ScientificNumber.One:ScientificNumber.FromData(p.value));}
  public static void Validate(LegacyState s){if(s==null||s.licenses==null||s.autobuyers==null||s.cycle==null||s.permanent==null||s.licenses.Distinct().Count()!=s.licenses.Length||s.licenses.Any(x=>string.IsNullOrEmpty(x)||x.Length>80)||s.autobuyers.Any(id=>!Balance.Hardware.Any(h=>h.Id==id))||!ScientificNumber.Finite(s.trainingBoostUntil)||s.trainingBoostUntil<0||s.scannerTarget< -1||s.scannerTarget>=10)throw new FormatException("Invalid preserved legacy effects");foreach(var map in new[]{s.cycle,s.permanent}){if(map.Length>100||map.Any(x=>x==null||string.IsNullOrEmpty(x.key)||x.key.Length>80)||map.Select(x=>x.key).Distinct().Count()!=map.Length)throw new FormatException("Invalid legacy factors");foreach(var f in map)ScientificNumber.FromData(f.value);}}
 }
}
